INSERT INTO questions (id, sort_order, question, type, choices, answer, is_active) VALUES
('q1', 1, '警察に無免許運転で注意され、指名手配されました。手配度を消すためにジョブを変更して回避することは可能ですか？', 'radio', '["手配状況は引き続かれるため、現在のジョブは変更できない。ジョブを変えたい場合は手配度が切れてから変える必要がある。","可能である。","どうしても変えたい場合に限って可能である。"]', '"手配状況は引き続かれるため、現在のジョブは変更できない。ジョブを変えたい場合は手配度が切れてから変える必要がある。"', 1),
('q2', 2, 'あなたは信号のない交差点を直進しようとしています。交差する道路には「一時停止」の標識はありませんが、見通しが悪い状況です。どのように進行すべきですか？', 'radio', '["そのままの速度で進行する。","安全のため、一時停止してから進入する。","速度を上げて一気に通過する。"]', '"安全のため、一時停止してから進入する。"', 1),
('q3', 3, '対向車線の車がセンターラインを越えてきたため、正面衝突事故を起こしてしまいました。まず取るべき行動として最も適切なものはどれですか？', 'radio', '["車を安全な場所に停車させ、エンジンを切り、まず相手のドライバーの安否を確認する。","警察が来るまで車の中に留まり、何もしない。","警察を呼んで現場を立ち去る。"]', '"車を安全な場所に停車させ、エンジンを切り、まず相手のドライバーの安否を確認する。"', 1),
('q4', 4, '他のプレイヤーが明らかに荒らし行為（無差別な衝突、暴言、車両の破損）を行っています。あなたはどう対応しますか？', 'radio', '["自分もやり返して荒らしを止める。","荒らし行為の証拠（スクリーンショットや回画など）を確保し、ロールプレイを続けながら運営・ホストへ報告する。","その場から逃げ去り、無視する。"]', '"荒らし行為の証拠（スクリーンショットや回画など）を確保し、ロールプレイを続けながら運営・ホストへ報告する。"', 1),
('q5', 5, 'あなたの走行中、後方からサイレンを鳴らした救急車が接近してきました。あなたは前方に赤信号の交差点がありますが、どのように対処しますか？ （具体的にお答えください）', 'text', NULL, NULL, 1),
('q6', 6, '対抗車線を使用しての車の追い越しは可能ですか？', 'radio', '["可能である。","不可能である。","可能である。ただし、違反回数が（4回）としてカウントされる。"]', '"可能である。ただし、違反回数が（4回）としてカウントされる。"', 1),
('q7', 7, '駐車禁止場所に指定されているのは次のうちどれですか？ [複数選択]', 'checkbox', '["デパートの駐車場。","バーガーハウスの駐車場。","交差点のすぐ手前。"]', '["交差点のすぐ手前。","バーガーハウスの駐車場。"]', 1),
('q8', 8, '道路の横にあり、道路と違う色が塗られている帯（路肩・自転車レーン等）での追い越しは可能ですか？', 'radio', '["可能である。ただし、違反回数が（4回）としてカウントされる。","不可能である。","何も方向に広くとした空き地（草原）。"]', '"何も方向に広くとした空き地（草原）。"', 1);
